import openpyxl, datetime
from openpyxl.utils import get_column_letter
wb=openpyxl.load_workbook('/root/data/workbook.xlsx',data_only=False)
data=wb['Data']

# Scan a reasonable area for year-like headers (int/float/str/datetime) in rows 1-30
hits=[]
for r in range(1,41):
    for c in range(1,61):
        v=data.cell(row=r,column=c).value
        if v is None or v=='':
            continue
        # year int
        if isinstance(v,int) and 1900 < v < 2200:
            hits.append((r,get_column_letter(c),v,'int'))
        elif isinstance(v,float) and v.is_integer() and 1900 < int(v) < 2200:
            hits.append((r,get_column_letter(c),int(v),'float-int'))
        elif isinstance(v,str) and v.strip().isdigit() and 1900 < int(v.strip()) < 2200:
            hits.append((r,get_column_letter(c),int(v.strip()),'str'))
        elif isinstance(v,(datetime.date,datetime.datetime)):
            # if a date, see if year 2019-2023 maybe
            yr=v.year
            if 1900<yr<2200:
                hits.append((r,get_column_letter(c),v,'date'))

print('Year header candidate cells found:', len(hits))
for h in hits[:50]:
    print(h)

# Additionally list non-empty cells for row 20 and 19 in columns H-L, maybe formulas?
for r in [19,20]:
    for c in range(1,20):
        cell=data.cell(row=r,column=c)
        if cell.value is not None:
            print(f'{cell.coordinate}={cell.value!r} type={type(cell.value)}')

# Print column letters H-L row 20 values exactly
for c in range(8,13):
    cell=data.cell(row=20,column=c)
    print(cell.coordinate, cell.value, cell.data_type)

